import java.util.Set;

/**
 * The filter {@link CustomerRepository} applies to a page query and to a count
 * query alike.
 *
 * <p>A customer passes when it satisfies both halves:
 *
 * <ul>
 * <li>every whitespace-separated term of {@code name} is a substring of the
 * customer's first or last name, ignoring case and accents;
 * <li>the customer's status is one of {@code statuses}.
 * </ul>
 *
 * <p>Either half may be left empty, and an empty half matches every customer;
 * {@link #EMPTY} therefore matches the whole data set.
 *
 * @param name     the terms to look for, separated by whitespace; never
 *                 {@code null} after construction
 * @param statuses the statuses to keep, or empty for all of them; never
 *                 {@code null} after construction
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
    }

    /** Whether this filter lets every customer through. */
    public boolean isEmpty() {
        return name.isBlank() && statuses.isEmpty();
    }
}
