@@ -0,0 +1,171 @@
+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+
+import com.example.Application;
+import com.example.customers.domain.QueryLog;
+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.BrowserType;
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.AfterAll;
+import org.junit.jupiter.api.BeforeAll;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.junit.jupiter.api.TestInstance;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+/**
+ * The half of the specification that only a browser can see: what the address
+ * bar says, and what typing costs the backend.
+ *
+ * <p>Named {@code …IT} so that it stays out of {@code mvn test}, which is meant
+ * to remain a fast, browserless suite. Run it with
+ * {@code mvn -o test -Dtest=CustomerFilterBrowserIT}.
+ */
+@SpringBootTest(classes = Application.class,
+        webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+@TestInstance(TestInstance.Lifecycle.PER_CLASS)
+class CustomerFilterBrowserIT {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    private Page page;
+
+    @BeforeAll
+    static void launchBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch(new BrowserType.LaunchOptions()
+                .setArgs(List.of("--no-sandbox")));
+    }
+
+    @AfterAll
+    static void closeBrowser() {
+        if (browser != null) {
+            browser.close();
+        }
+        if (playwright != null) {
+            playwright.close();
+        }
+    }
+
+    @BeforeEach
+    void openPage() {
+        if (page == null) {
+            page = browser.newPage();
+        }
+    }
+
+    private void open(String path) {
+        page.navigate("http://localhost:" + port + path);
+        page.locator("vaadin-grid").waitFor();
+        page.waitForFunction("() => document.querySelector('vaadin-grid') "
+                + "&& document.querySelector('vaadin-grid').querySelectorAll('vaadin-grid-cell-content').length > 0");
+    }
+
+    private Locator nameFilter() {
+        return page.locator("vaadin-text-field input");
+    }
+
+    private String summary() {
+        return page.locator("span").first().textContent();
+    }
+
+    private String queryString() {
+        String url = page.url();
+        int start = url.indexOf('?');
+        return (start < 0) ? "" : url.substring(start + 1);
+    }
+
+    @Test
+    void typingNarrowsTheListWithoutOneQueryPerKeystroke() {
+        open("/");
+        assertEquals("Showing 500 of 500", summary());
+
+        queryLog.clear();
+        nameFilter().pressSequentially("aaltonen",
+                new Locator.PressSequentiallyOptions().setDelay(60));
+
+        page.waitForFunction("() => document.querySelector('span')"
+                + " && document.querySelector('span').textContent !== 'Showing 500 of 500'");
+        assertEquals("Showing 15 of 500", summary());
+
+        // One filter application, not eight: the grid asks for one page and one
+        // count, and the summary asks for its own count.
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing eight letters ran " + queryLog.pageQueries().size()
+                        + " page queries; the filter must be debounced, not sent per keystroke");
+        assertTrue(queryLog.countQueries().size() <= 4,
+                "Typing eight letters ran " + queryLog.countQueries().size() + " count queries");
+        assertTrue(queryLog.rowsFetched() <= 200,
+                "Typing pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    @Test
+    void theFilterReachesTheAddressBar() {
+        open("/");
+        assertEquals("", queryString(), "an empty filter leaves no parameters behind");
+
+        nameFilter().fill("vir");
+        page.waitForURL("**/?name=vir");
+        assertEquals("name=vir", queryString());
+
+        page.getByRole(AriaRole.COMBOBOX).click();
+        page.getByRole(AriaRole.OPTION).filter(
+                new Locator.FilterOptions().setHasText("ACTIVE")).first().click();
+        page.getByRole(AriaRole.OPTION).filter(
+                new Locator.FilterOptions().setHasText("CLOSED")).first().click();
+        page.keyboard().press("Escape");
+
+        page.waitForURL("**/?name=vir&status=ACTIVE,CLOSED");
+        assertEquals("name=vir&status=ACTIVE,CLOSED", queryString(),
+                "statuses are listed in declaration order, comma-separated");
+
+        nameFilter().fill("");
+        page.waitForURL("**/?status=ACTIVE,CLOSED");
+        assertEquals("status=ACTIVE,CLOSED", queryString());
+    }
+
+    @Test
+    void typingDoesNotFillUpTheHistory() {
+        open("/");
+        int before = (int) (Integer) page.evaluate("() => window.history.length");
+
+        nameFilter().pressSequentially("virtanen",
+                new Locator.PressSequentiallyOptions().setDelay(60));
+        page.waitForURL("**/?name=virtanen");
+
+        int after = (int) (Integer) page.evaluate("() => window.history.length");
+        assertEquals(before, after,
+                "filtering replaced the history entry rather than pushing new ones");
+    }
+
+    @Test
+    void aSharedLinkOpensTheFilteredList() {
+        open("/?name=vir&status=ACTIVE,CLOSED");
+
+        assertEquals("vir", nameFilter().inputValue());
+        assertEquals(List.of("ACTIVE", "CLOSED"),
+                page.evaluate("() => document.querySelector('vaadin-multi-select-combo-box')"
+                        + ".selectedItems.map(item => item.label)"),
+                "the status field must show the filter from the URL");
+        assertEquals("Showing 10 of 500", summary());
+        assertEquals("name=vir&status=ACTIVE,CLOSED", queryString(),
+                "reading the URL must not rewrite it");
+    }
+}
